package clusterdata.utils;

import clusterdata.datatypes.JobEvent;

import java.io.FileInputStream;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;
import java.util.zip.GZIPInputStream;

public class JobCompletionFilter {
    /**
     * Load finished jobs from job event file.
     * Returns a set of job IDs that have event type FINISH (2)
     */
    public static Set<Integer> loadFinishedJobs(String jobEventPath) throws Exception {
        Set<Integer> finishedJobs = new HashSet<>();

        try (GZIPInputStream gzip = new GZIPInputStream(new FileInputStream(jobEventPath));
             Scanner scanner = new Scanner(gzip)) {

            while (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                String[] fields = line.split(",", -1);

                // Extract event type (field index 3) and job ID (field index 2)
                int eventType = parseInt(fields, 3);
                int jobId = parseInt(fields, 2);

                if (eventType == JobEvent.FINISH) {
                    finishedJobs.add(jobId);
                }
            }
        }

        return finishedJobs;
    }

    private static int parseInt(String[] fields, int index) {
        if (index >= fields.length) return -1;
        String val = fields[index].trim();
        return val.isEmpty() ? -1 : Integer.parseInt(val);
    }
}

